insert into public.quiz_questions (question, options, correct_index, explanation, reference, category, difficulty) values
('Which day does the Bible identify as the Sabbath?', '["The first day (Sunday)", "The seventh day (Saturday)", "Friday", "Any day you choose"]'::jsonb, 1, 'God blessed and sanctified the seventh day; the fourth commandment says keep it holy.', 'Exodus 20:8-11', 'Sabbath', 'easy'),
('According to the Bible, what happens to a person at death?', '["They go straight to heaven", "They sleep, awaiting the resurrection", "They become an angel", "They are reincarnated"]'::jsonb, 1, 'The dead know nothing and sleep until Jesus calls them at the resurrection.', 'Ecclesiastes 9:5; John 11:11-14', 'State of the Dead', 'medium'),
('How will Jesus'' second coming be?', '["Secret and invisible", "Spiritual only", "Literal and visible - every eye shall see Him", "Through the church"]'::jsonb, 2, 'Behold, He comes with clouds, and every eye shall see Him.', 'Revelation 1:7; Acts 1:11', 'Second Coming', 'easy'),
('In how many days did God create the heavens and the earth before resting?', '["Three", "Six", "Seven", "Twelve"]'::jsonb, 1, 'God created in six days and rested on the seventh - the basis of the Sabbath.', 'Genesis 1; Exodus 20:11', 'Creation', 'easy'),
('The gift of prophecy in the remnant church was manifested through whom?', '["Ellen G. White", "Martin Luther", "William Miller", "Joseph Bates"]'::jsonb, 0, 'Adventists recognise the Spirit of Prophecy through the ministry of Ellen G. White.', 'Revelation 12:17; 19:10', 'Spirit of Prophecy', 'medium'),
('After His ascension, where did Jesus begin His ministry as High Priest?', '["On earth", "In the heavenly sanctuary", "In Jerusalem", "In the church"]'::jsonb, 1, 'Jesus ministers in the true tabernacle in heaven.', 'Hebrews 8:1-2', 'Sanctuary', 'medium'),
('What does the Bible say our body is?', '["Just flesh", "The temple of the Holy Spirit", "Unimportant", "Ours to abuse"]'::jsonb, 1, 'We are to glorify God in our body - a basis of the health message.', '1 Corinthians 6:19-20', 'Health', 'easy'),
('In Daniel 2, the head of gold on the great image represented which kingdom?', '["Medo-Persia", "Greece", "Babylon", "Rome"]'::jsonb, 2, 'You are this head of gold - Babylon under Nebuchadnezzar.', 'Daniel 2:38', 'Prophecy', 'medium'),
('How many commandments did God write with His own finger on stone?', '["Seven", "Ten", "Twelve", "Forty"]'::jsonb, 1, 'God wrote the Ten Commandments on two tables of stone.', 'Exodus 34:28; 31:18', 'Law', 'easy'),
('How is a person saved according to the Bible?', '["By works alone", "By grace through faith in Jesus", "By church membership", "By keeping rules"]'::jsonb, 1, 'Salvation is the gift of God, by grace through faith, not of works.', 'Ephesians 2:8-9', 'Salvation', 'easy'),
('What mode of baptism does the New Testament teach?', '["Sprinkling", "Pouring", "Immersion", "Anointing"]'::jsonb, 2, 'Baptism is by immersion - death, burial and resurrection with Christ.', 'Romans 6:3-4; Matthew 3:16', 'Baptism', 'medium'),
('What portion of our increase is the tithe?', '["A fifth", "A tenth", "A half", "Whatever is left over"]'::jsonb, 1, 'The tithe is a tenth, and it is holy to the Lord.', 'Malachi 3:10; Leviticus 27:30', 'Stewardship', 'easy'),
('The 2300 days of Daniel 8:14 point to the cleansing of the...', '["Temple in Jerusalem", "Heavenly sanctuary (judgment beginning 1844)", "Earth", "Church"]'::jsonb, 1, 'Adventists understand this as the start of the investigative judgment in 1844.', 'Daniel 8:14', 'Prophecy', 'hard'),
('Where are the three angels'' messages found?', '["Daniel 7", "Matthew 24", "Revelation 14", "Isaiah 58"]'::jsonb, 2, 'The three angels'' messages are God''s final warning to the world.', 'Revelation 14:6-12', 'Prophecy', 'medium'),
('What are the wages of sin?', '["Sickness", "Death", "Poverty", "Sadness"]'::jsonb, 1, 'The wages of sin is death, but the gift of God is eternal life.', 'Romans 6:23', 'Salvation', 'easy'),
('Besides Enoch, which prophet was taken to heaven without dying?', '["Moses", "Elijah", "Isaiah", "Daniel"]'::jsonb, 1, 'Elijah was taken up by a whirlwind in a chariot of fire.', '2 Kings 2:11', 'Bible Characters', 'medium'),
('In Revelation 20, how long is the millennium?', '["100 years", "500 years", "1000 years", "Forever"]'::jsonb, 2, 'The saints reign with Christ a thousand years.', 'Revelation 20:2-7', 'Prophecy', 'medium'),
('The remnant of Revelation 12:17 keep God''s commandments and have what?', '["Great wealth", "The testimony of Jesus", "Political power", "Many members"]'::jsonb, 1, 'The remnant keep God''s commandments and have the testimony of Jesus.', 'Revelation 12:17; 19:10', 'Prophecy', 'medium'),
('Before Communion, Adventists practise which ordinance of humility?', '["Anointing with oil", "Foot washing", "Incense", "Fasting"]'::jsonb, 1, 'Jesus washed the disciples'' feet and told them to do likewise.', 'John 13:4-15', 'Doctrine', 'medium'),
('What did Jesus promise to prepare for His followers?', '["Riches now", "A place / mansions", "An earthly kingdom", "Freedom from work"]'::jsonb, 1, 'I go to prepare a place for you, that where I am, there you may be also.', 'John 14:1-3', 'Second Coming', 'easy'),
('What was Jesus'' first recorded miracle?', '["Healing a leper", "Walking on water", "Turning water into wine at Cana", "Feeding 5000"]'::jsonb, 2, 'At a wedding in Cana, Jesus turned water into wine.', 'John 2:1-11', 'Bible Characters', 'easy'),
('How many books are in the Protestant Bible?', '["27", "39", "66", "73"]'::jsonb, 2, '39 in the Old Testament and 27 in the New Testament make 66.', '-', 'Bible Basics', 'easy'),
('The fruit of the Spirit begins with which quality?', '["Joy", "Peace", "Love", "Patience"]'::jsonb, 2, 'The fruit of the Spirit is love, joy, peace...', 'Galatians 5:22-23', 'Christian Living', 'easy'),
('In Daniel 7, the little-horn power sought to change what?', '["Times and laws", "Kings", "The seasons", "The language"]'::jsonb, 0, 'It would think to change times and laws - tampering with God''s law.', 'Daniel 7:25', 'Prophecy', 'hard'),
('Leviticus 11 distinguishes between which two categories of food?', '["Cheap and costly", "Clean and unclean", "Cooked and raw", "Old and fresh"]'::jsonb, 1, 'God identified clean and unclean meats, relevant to the health message.', 'Leviticus 11', 'Health', 'medium'),
('What is the second death in Revelation?', '["Sleeping in the grave", "Final destruction of the wicked in the lake of fire", "Persecution", "Old age"]'::jsonb, 1, 'The lake of fire is the second death - the final end of sin and sinners.', 'Revelation 20:14; 21:8', 'State of the Dead', 'medium'),
('Who is the Head of the church?', '["The pastor", "The conference president", "Jesus Christ", "Ellen White"]'::jsonb, 2, 'Christ is the head of the body, the church.', 'Ephesians 1:22; Colossians 1:18', 'Doctrine', 'easy'),
('What did Jesus say is the greatest commandment?', '["Keep the Sabbath", "Love God with all your heart", "Pay tithe", "Be baptised"]'::jsonb, 1, 'Love the Lord your God with all your heart is the first and great commandment.', 'Matthew 22:37-38', 'Christian Living', 'easy'),
('On which day did God rest, bless and sanctify after creation?', '["The first day", "The sixth day", "The seventh day", "The eighth day"]'::jsonb, 2, 'God rested the seventh day and made it holy.', 'Genesis 2:2-3', 'Sabbath', 'easy'),
('Without what is it impossible to please God?', '["Money", "Faith", "Knowledge", "Works"]'::jsonb, 1, 'Without faith it is impossible to please Him.', 'Hebrews 11:6', 'Salvation', 'medium'),
('The Great Disappointment, when Christ did not return as expected, occurred in which year?', '["1798", "1844", "1863", "1888"]'::jsonb, 1, 'On 22 October 1844 the Millerites expected Christ''s return; the disappointment led to deeper study of the sanctuary.', 'Daniel 8:14', 'Adventist History', 'medium'),
('The Millerite movement that preached the soon return of Christ was led by whom?', '["James White", "William Miller", "Joseph Bates", "John N. Andrews"]'::jsonb, 1, 'William Miller, a Baptist preacher, proclaimed the 1844 message from Daniel 8:14.', '-', 'Adventist History', 'medium'),
('In which year was the Seventh-day Adventist Church officially organised?', '["1844", "1860", "1863", "1901"]'::jsonb, 2, 'The General Conference of Seventh-day Adventists was organised in 1863 in Battle Creek, Michigan.', '-', 'Adventist History', 'hard'),
('Which pioneer is especially known for bringing the Sabbath truth to the early Adventists?', '["Joseph Bates", "William Miller", "Hiram Edson", "Uriah Smith"]'::jsonb, 0, 'Joseph Bates, a retired sea captain, championed the seventh-day Sabbath among the pioneers.', '-', 'Adventist History', 'hard'),
('In which year was the name ''Seventh-day Adventist'' chosen?', '["1844", "1860", "1888", "1901"]'::jsonb, 1, 'The name Seventh-day Adventist was adopted in 1860, reflecting the Sabbath and the Advent hope.', '-', 'Adventist History', 'hard'),
('Ellen and James White, together with which pioneer, are often called co-founders of the church?', '["Joseph Bates", "Charles Fitch", "Josiah Litch", "John Wesley"]'::jsonb, 0, 'Ellen White, James White and Joseph Bates are recognised as principal co-founders.', '-', 'Adventist History', 'medium'),
('Adventist health work led to the founding of which well-known medical institution in California?', '["Johns Hopkins", "Loma Linda University", "Harvard Medical", "Mayo Clinic"]'::jsonb, 1, 'Loma Linda University grew out of the Adventist health and medical-missionary work.', '-', 'Adventist History', 'medium'),
('In which U.S. town was the early Adventist headquarters and the famous sanitarium located?', '["Washington, D.C.", "Battle Creek, Michigan", "Takoma Park", "Nashville"]'::jsonb, 1, 'Battle Creek, Michigan was the early church centre and home of the Battle Creek Sanitarium.', '-', 'Adventist History', 'hard');
